using System.Globalization;
using Playroma.Text.Core.Dialogue;
using Playroma.Text.Core.Generation;
using Playroma.Text.Generators.Dialogue;

namespace Playroma.Text.Generators.Stages;

/// <summary>Applies a reusable character voice profile to dialogue fields already generated by earlier recipe stages.</summary>
public sealed class DialogueVoiceStage : ITextGenerationStage
{
    public const string StageKind = "phase10.voice";
    private readonly DialogueVoiceProfileRegistry _profiles;
    private readonly DialogueVoiceEngine _engine = new();

    public DialogueVoiceStage(DialogueVoiceProfileRegistry profiles) => _profiles = profiles ?? throw new ArgumentNullException(nameof(profiles));
    public string Kind => StageKind;

    public async ValueTask<GenerationStageResult> ExecuteAsync(GenerationStageContext context, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        string profileContextKey = StageSettingsReader.GetString(context.Stage, "profileContextKey", "voice.profileId");
        string profileId = Value(context, profileContextKey)
            ?? StageSettingsReader.GetString(context.Stage, "profileId", "common");
        DialogueVoiceProfile? profile = await _profiles.ResolveAsync(profileId, cancellationToken).ConfigureAwait(false);
        if (profile is null)
            return GenerationStageResult.Fail(context.WorkingBundle, new GenerationDiagnostic(
                GenerationDiagnosticCodes.UnknownVoiceProfile, GenerationDiagnosticSeverity.Error,
                $"Dialogue voice profile '{profileId}' was not found.", context.Stage.Id));
        var profileErrors = DialogueVoiceProfileValidator.Validate(profile);
        if (profileErrors.Count != 0)
            return GenerationStageResult.Fail(context.WorkingBundle, new GenerationDiagnostic(
                GenerationDiagnosticCodes.InvalidVoiceProfile, GenerationDiagnosticSeverity.Error,
                "Dialogue voice profile is invalid: " + string.Join(" ", profileErrors), context.Stage.Id));

        DialogueAct act = ParseEnum(Value(context, "dialogue.act") ?? StageSettingsReader.GetString(context.Stage, "act", "SmallTalk"), DialogueAct.SmallTalk);
        DialogueEmotion emotion = ParseEnum(Value(context, "voice.emotion") ?? Value(context, "dialogue.emotion") ?? StageSettingsReader.GetString(context.Stage, "emotion", profile.DefaultEmotion.ToString()), profile.DefaultEmotion);
        var options = new DialogueVoiceRealizationOptions(
            act,
            emotion,
            Number(context, "relationship.affinity", 0),
            Number(context, "relationship.trust", 0),
            Value(context, "speaker.name"),
            Value(context, "listener.name"),
            StageSettingsReader.GetBool(context.Stage, "addActFraming", true),
            StageSettingsReader.GetBool(context.Stage, "addEmotionFraming", true),
            StageSettingsReader.GetBool(context.Stage, "addCatchphrase", true),
            StageSettingsReader.GetBool(context.Stage, "applyDialect", true),
            StageSettingsReader.GetBool(context.Stage, "applyVocabulary", true),
            StageSettingsReader.GetString(context.Stage, "tabooReplacement", "…"));
        IReadOnlyList<string> fields = StageSettingsReader.GetStringArray(context.Stage, "fields");
        GeneratedTextBundle bundle = _engine.Apply(context.WorkingBundle, profile, options, context.Random, fields.Count == 0 ? null : fields);
        context.Trace.Add(context.Stage.Id, "dialogue-voice", null, context.WorkingBundle.PrimaryText, bundle.PrimaryText,
            new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase)
            {
                ["profile"] = profile.Id,
                ["speaker"] = options.SpeakerName ?? string.Empty,
                ["act"] = act.ToString(),
                ["emotion"] = emotion.ToString()
            });
        return GenerationStageResult.Ok(bundle);
    }

    private static string? Value(GenerationStageContext context, string key)
    {
        if (!context.Context.Data.TryGetValue(key, out object? value) || value is null) return null;
        return Convert.ToString(value, CultureInfo.InvariantCulture);
    }

    private static double Number(GenerationStageContext context, string key, double fallback)
    {
        if (!context.Context.Data.TryGetValue(key, out object? value) || value is null) return fallback;
        try { return Convert.ToDouble(value, CultureInfo.InvariantCulture); } catch { return fallback; }
    }

    private static T ParseEnum<T>(string? value, T fallback) where T : struct, Enum =>
        !string.IsNullOrWhiteSpace(value) && Enum.TryParse<T>(value, true, out var parsed) ? parsed : fallback;
}
